const menu=document.querySelector('#menu');menu.onclick=()=>{const open=menu.getAttribute('aria-expanded')!=='true';menu.setAttribute('aria-expanded',open);document.querySelector('#nav').classList.toggle('open',open)};
const slug=new URLSearchParams(location.search).get('page');
if(slug){document.querySelector('#home').hidden=true;document.querySelector('#detail').hidden=false;fetch('content.json').then(r=>r.json()).then(pages=>{const page=pages[slug];if(!page){document.querySelector('#page-title').textContent='Page not found';document.querySelector('#article').innerHTML='<p>Explore the program using the links on this page.</p>';return}document.title=page.title+' | Millennium Scholars';document.querySelector('#page-title').textContent=page.title;document.querySelector('#crumb').textContent=page.title;document.querySelector('#article').innerHTML=page.html;const directory=document.querySelector('#directory');const entries=Object.entries(pages).sort((a,b)=>a[1].title.localeCompare(b[1].title));const render=q=>{directory.replaceChildren();for(const [key,p] of entries){if(!p.title.toLowerCase().includes(q.toLowerCase()))continue;const a=document.createElement('a');a.href='?page='+key;a.textContent=p.title;if(key===slug)a.setAttribute('aria-current','page');directory.append(a)}if(!directory.children.length)directory.textContent='No matching pages.'};render('');document.querySelector('#search').oninput=e=>render(e.target.value);if(slug==='faq'){const article=document.querySelector('#article');for(const heading of [...article.querySelectorAll('h5')]){const d=document.createElement('details'),s=document.createElement('summary');s.textContent=heading.textContent;heading.replaceWith(d);d.append(s);while(d.nextSibling&&!/^H[1-6]$/.test(d.nextSibling.nodeName)){d.append(d.nextSibling)}}}}).catch(()=>{document.querySelector('#page-title').textContent='Unable to load this page';document.querySelector('#article').innerHTML='<p>Please refresh or <a href="https://www.millennium.psu.edu/">visit the original website</a>.</p>'})}
